;; S5D oracle probe: core-var survey (arithmetic, comparison, predicates,
;; strings, collections, seqs, higher-order, control macros, exceptions,
;; IO, trampoline/flags, special forms, arity errors). Exit 0 (caught).
(defn tx [label f]
  (println label "=>" (pr-str (try (f) (catch Throwable t
    (loop [t t acc []] (if t (recur (.getCause t) (conj acc (str (.getName (class t)) " | " (.getMessage t)))) acc)))))))
(defn cap [f] (try (f) (catch Throwable t (str (.getName (class t)) " | " (.getMessage t)))))
