(tx "read-string-edges" (fn [] [(read-string "[1 2]") (cap #(read-string "")) (cap #(read-string "   ")) (read-string "1 2") (read-string ":a") (read-string "\"s\"") (read-string "(+ 1 2)")]))
(tx "read-string-err" (fn [] [(cap #(read-string "(1 2")) (cap #(read-string "#"))]))
(tx "trampoline-edges" (fn [] [(trampoline (fn [] 1)) (trampoline + 1 2) (letfn [(o39 [n] (if (zero? n) :even0-stub (fn [] (e39 (dec n))))) (e39 [n] (if (zero? n) :even0 (fn [] (o39 (dec n)))))] (trampoline o39 101)) (cap #(trampoline 42))]))
