(tx "let-destructure" (fn [] [(let [{:keys [a b] :or {b 2} :as m} {:a 1}] [a b m]) (let [[x y & more :as v] [1 2 3 4]] [x y more v]) (let [{a :a} nil] a) (let [{{deep :d} :n} {:n {:d 9}}] deep) (let [[a [b c]] [1 [2 3]]] [a b c])]))
(tx "loop-recur" (fn [] [(loop [i 0 acc []] (if (= i 3) acc (recur (inc i) (conj acc i)))) (loop [x 5] (if (pos? x) (recur (dec x)) :done))]))
(tx "fn-arities" (fn [] [(let [f (fn ([x] [:one x]) ([x y] [:two x y]) ([x y & z] [:many x y z]))] [(f 1) (f 1 2) (f 1 2 3 4)]) ((fn [x & xs] [x xs]) 1 2 3) ((fn self [n] (if (zero? n) :zero (self (dec n)))) 3)]))
(tx "binding-restore" (fn [] (do (def ^:dynamic b39dyn :root) [(binding [b39dyn 1] b39dyn) b39dyn (binding [b39dyn 1] (binding [b39dyn 2] b39dyn)) (do (try (binding [b39dyn 1] (throw (Exception. "x"))) (catch Exception e)) b39dyn)])))
(tx "letfn-mutual" (fn [] [(letfn [(e39b [n] (if (zero? n) true (o39b (dec n)))) (o39b [n] (if (zero? n) false (e39b (dec n))))] [(e39b 10) (o39b 7)])]))
(tx "special-macroexpand" (fn [] [(macroexpand-1 '(let [x 1] x)) (macroexpand-1 '(loop [x 1] x)) (macroexpand-1 '(fn [x] x)) (first (macroexpand '(and a b))) (first (macroexpand '(or a b))) (first (macroexpand '(when a b)))]))
(tx "recur-mismatch" (fn [] [(cap #(eval '(fn [x] (recur 1 2)))) (cap #(eval '(recur 1)))]))
(tx "arity-nth-conj-get" (fn [] [(cap #(nth [1])) (cap #(conj)) (cap #(get {:a 1}))]))
(tx "arity-kw-call" (fn [] [(:a {:a 1}) (:b {:a 1} :dflt) (cap #(:a {:a 1} :d :extra))]))
